insert into public.shops (id, slug, seller_id, name, tagline, category, district, tehsil, town, bazaar, verifications, rating, review_count, followers, trade_mode, delivery, accepts_orders, hours, cover_url, logo_url, monogram, about, founded, payments, delivery_note, highlights, address, status) values
  ('shop-1', 'hunza-dry-fruits-house', 's-hunza-dfh', 'Hunza Dry Fruits House', 'Apricots, walnuts & almonds from Hunza orchards since 1998', 'dry-fruits', 'hunza', 'aliabad', 'Aliabad', 'aliabad-market', array['phone', 'identity', 'business', 'rego']::text[], 4.8, 126, 2140, 'both', true, true, '{"open":"09:00","close":"20:00","days":"Mon – Sat"}'::jsonb, 'https://images.unsplash.com/photo-1583440772344-edd2e043742c?auto=format&fit=crop&w=1600&q=80', null, 'HD', array['A family shop on the Aliabad main road, selling dry fruits from our own and neighbours'' orchards in central Hunza since 1998.', 'Everything is sun-dried on rooftops and hand-sorted before packing. We sell by the KG for homes and by the sack for shops and hotels.']::text[], 1998, array['Cash on delivery', 'Easypaisa', 'JazzCash', 'Bank transfer']::text[], 'Delivers across Gilgit-Baltistan in 1–3 days. Same-day in Aliabad and Karimabad.', array['Sun-dried, hand-sorted', 'Wholesale rates for shops', 'Gift packing available']::text[], 'Main KKH Road, near Aliabad Chowk, Hunza', 'active'),
  ('shop-2', 'shigar-organic-farms', 's-shigar-organic', 'Shigar Organic Farms', 'Family orchards in Shigar valley — sun-dried, chemical-free', 'dry-fruits', 'shigar', null, 'Shigar', 'shigar-market', array['phone', 'identity', 'business']::text[], 4.9, 88, 1260, 'wholesale', true, true, '{"open":"08:00","close":"18:00","days":"Daily"}'::jsonb, 'https://images.unsplash.com/photo-1748596499389-693c1f1569af?auto=format&fit=crop&w=1600&q=80', null, 'SO', array['Three families farming apricot, walnut and almond orchards in Shigar valley. No chemical sprays, no sulphur on our apricots.', 'Most of our trade is wholesale to shops in Skardu, Gilgit and down-country, but we also send small orders to homes.']::text[], 2016, array['Cash on delivery', 'Easypaisa', 'Bank transfer']::text[], 'Delivers across GB. Wholesale orders go by cargo to Rawalpindi and Islamabad.', array['No sulphur', 'Direct from the orchard', 'Bulk from 40 KG']::text[], 'Shigar Fort Road, Shigar', 'active'),
  ('shop-3', 'baltistan-motors', 's-baltistan-motors', 'Baltistan Motors', 'Inspected 4x4s, jeeps and cars for mountain roads', 'vehicles', 'skardu', null, 'Skardu City', 'skardu-bazaar', array['phone', 'identity', 'business', 'rego']::text[], 4.7, 64, 3310, 'retail', false, false, '{"open":"10:00","close":"19:00","days":"Mon – Sat"}'::jsonb, 'https://images.unsplash.com/photo-1656685299734-52a0bb4425aa?auto=format&fit=crop&w=1600&q=80', null, 'BM', array['Skardu''s longest-running used-car showroom. Every vehicle is inspected by our mechanic before it goes on sale, and papers are checked at Excise.', 'Come see any car at the showroom. Test drives on the Skardu–Shigar road are welcome.']::text[], 2009, array['Cash at shop', 'Bank transfer']::text[], 'No delivery. See and test drive at our Skardu showroom.', array['Mechanic-inspected', 'Papers verified', 'Test drive welcome']::text[], 'Hussaini Chowk, College Road, Skardu City', 'active'),
  ('shop-4', 'karakoram-mobile-zone', 's-karakoram-mobile', 'Karakoram Mobile Zone', 'PTA-approved phones, accessories and repairs', 'electronics', 'gilgit', null, 'Jutial', 'gilgit-bazaar', array['phone', 'business']::text[], 4.6, 203, 4870, 'both', true, true, '{"open":"10:00","close":"21:00","days":"Daily"}'::jsonb, 'https://images.unsplash.com/photo-1697545806245-9795b6056141?auto=format&fit=crop&w=1600&q=80', null, 'KM', array['PTA-approved phones, laptops and accessories in Jutial, with a repair counter for screens, batteries and charging ports.', 'Used devices come with a 7-day check warranty. New items carry the brand or shop warranty written on the bill.']::text[], 2014, array['Cash on delivery', 'Easypaisa', 'JazzCash', 'Bank transfer', 'Cash at shop']::text[], 'Delivers across GB in 1–2 days. Same-day in Gilgit city.', array['PTA approved', '7-day check warranty', 'Repairs in-house']::text[], 'Shop 12, Jutial Market, Gilgit', 'active'),
  ('shop-5', 'nagar-honey-herbs', 's-nagar-honey', 'Nagar Honey & Herbs', 'Raw wild honey, sea buckthorn and mountain herbs', 'dry-fruits', 'nagar', null, 'Hopar', null, array['phone', 'identity', 'business']::text[], 4.9, 57, 980, 'both', true, true, '{"open":"09:00","close":"18:00","days":"Mon – Sat"}'::jsonb, 'https://images.unsplash.com/photo-1586779161164-d89795b07b71?auto=format&fit=crop&w=1600&q=80', null, 'NH', array['Wild honey from the hives of Hopar and Nagar valleys, plus sea buckthorn and mountain herbs picked each summer.', 'Our honey is raw and unheated. We are happy to send a small sample jar before a large order.']::text[], 2019, array['Cash on delivery', 'Easypaisa', 'JazzCash']::text[], 'Delivers across GB in 2–3 days.', array['Raw & unheated', 'Sample jars on request', 'Picked in Nagar']::text[], 'Hopar Road, Nagar', 'active'),
  ('shop-6', 'khaplu-handicrafts-collective', 's-khaplu-crafts', 'Khaplu Handicrafts Collective', 'Women-led weaving, embroidery and woodwork from Ghanche', 'handicrafts', 'ghanche', null, 'Khaplu', 'khaplu-bazaar', array['phone', 'business', 'rego']::text[], 4.8, 41, 1530, 'both', true, true, '{"open":"09:30","close":"17:30","days":"Mon – Sat"}'::jsonb, 'https://images.unsplash.com/photo-1638310533874-6c124c012e1d?auto=format&fit=crop&w=1600&q=80', null, 'KH', array['A collective of 30+ women weavers and woodworkers from villages around Khaplu. Every piece is made by hand in Ghanche.', 'Buying here pays the maker directly. We take custom orders for rugs and embroidery.']::text[], 2012, array['Cash on delivery', 'Easypaisa', 'Bank transfer']::text[], 'Delivers across GB and Pakistan. Custom pieces take 2–4 weeks.', array['Handmade in Ghanche', 'Women-led', 'Custom orders']::text[], 'Khaplu Bazaar, near Chaqchan Mosque, Khaplu', 'active'),
  ('shop-7', 'deosai-outdoor-gear', 's-deosai-outdoor', 'Deosai Outdoor Gear', 'Tents, sleeping bags and trekking kit — sale & rental', 'cameras-gear', 'skardu', null, 'Skardu City', 'skardu-bazaar', array['phone', 'identity', 'business']::text[], 4.7, 72, 1745, 'retail', false, false, '{"open":"09:00","close":"20:00","days":"Daily"}'::jsonb, 'https://images.unsplash.com/photo-1599758376048-8c340c1489cb?auto=format&fit=crop&w=1600&q=80', null, 'DO', array['Trekking and camping kit for Deosai, K2 base camp and the Baltoro. Buy new or rent by the day.', 'All rental gear is cleaned and checked after every trip. Ask us about the route, we trek it ourselves.']::text[], 2015, array['Cash at shop', 'Easypaisa', 'JazzCash']::text[], 'Pickup from our Skardu shop. Rentals need a CNIC copy.', array['Sale & rental', 'Cleaned after every trip', 'Route advice']::text[], 'Yadgar Chowk, Main Bazaar, Skardu City', 'active'),
  ('shop-8', 'astore-livestock-traders', 's-astore-livestock', 'Astore Livestock Traders', 'Goats, sheep and cattle from Astore pastures', 'livestock', 'astore', null, 'Eidgah', null, array['phone', 'identity']::text[], 4.6, 35, 640, 'both', false, false, '{"open":"07:00","close":"18:00","days":"Daily"}'::jsonb, 'https://images.unsplash.com/photo-1579962568308-35dfb6da73f4?auto=format&fit=crop&w=1600&q=80', null, 'AL', array['Goats, sheep, yaks and cattle from Astore pastures. We buy from local herders and sell healthy, vaccinated animals.', 'Visit our pen in Eidgah to see the animals. We help arrange transport to Gilgit and Chilas.']::text[], 2020, array['Cash at shop', 'Bank transfer']::text[], 'See animals at our Eidgah pen. Transport to Gilgit can be arranged.', array['Vaccinated animals', 'Vet records', 'Transport help']::text[], 'Livestock Mandi, Eidgah, Astore', 'active');
