insert into public.wanted_requests (id, slug, buyer_name, buyer_type, buyer_verified, title, category, district, town, budget_min, budget_max, unit, negotiable, mode, quantity, details, need_by, offers, posted_at) values
  ('w-1', '500-kg-premium-walnut-gilgit', 'Raja Traders', 'Business', true, '500 KG Premium Walnut Required', 'dry-fruits', 'skardu', 'Skardu City', 1600, 1800, 'kg', false, 'Wholesale', '500 KG', null, null, 7, now() - interval '4 hours'),
