  ('w-3', '2-kanal-plot-jutial', 'Farhan Ahmed', 'Individual', false, '2 Kanal Residential Plot', 'property', 'gilgit', 'Jutial', 6000000, 8000000, null, false, 'Retail', null, null, null, 2, now() - interval '20 hours'),
  ('w-4', '1000-kg-dried-apricot-halman-shigar', 'Baltistan Agro Exports', 'Business', true, '1,000 KG Dried Apricot (Halman)', 'dry-fruits', 'shigar', 'Shigar', 900, 1100, 'kg', false, 'Wholesale', '1,000 KG', null, null, 11, now() - interval '27 hours'),
