  ('w-6', 'honda-125-2022-hunza', 'Sher Aziz', 'Individual', true, 'Honda 125 (2022 or newer)', 'vehicles', 'hunza', 'Aliabad', 200000, 240000, null, false, 'Retail', null, null, null, 5, now() - interval '41 hours'),
  ('w-7', 'iphone-13-or-14-gilgit', 'Nadia Karim', 'Individual', true, 'iPhone 13 or 14 (PTA approved)', 'electronics', 'gilgit', 'Konodas', 130000, 160000, null, false, 'Retail', null, 'Battery health above 85%. Box preferred. I can come to Jutial or Konodas to check it.', 'This week', 3, now() - interval '6 hours'),
  ('w-8', 'house-for-rent-danyore-family', 'Zulfiqar Ali', 'Individual', true, 'House for Rent (2–3 Bed) for a Family', 'property', 'gilgit', 'Danyore', null, 45000, 'month', false, 'Rent', null, 'Family of five. Need gas and water connection, parking for one car. Long-term rent.', 'From next month', 2, now() - interval '15 hours'),
  ('w-9', '200-kg-pure-honey-hotel-hunza', 'Eagle''s Nest Hotel', 'Business', true, '200 KG Pure Honey for a Hotel', 'dry-fruits', 'hunza', 'Karimabad', 3000, 3800, 'kg', false, 'Wholesale', '200 KG', 'Raw, unheated honey for guests. Monthly supply of about 20 KG after the first order. Lab test welcome.', 'Within 2 weeks', 6, now() - interval '22 hours'),
  ('w-10', 'pattu-shawls-for-shop-lahore', 'Heritage Crafts Lahore', 'Business', false, '50 Handmade Pattu Shawls for a Shop', 'handicrafts', 'ghanche', 'Khaplu', 7000, 9000, 'piece', false, 'Bulk', '50 pieces', 'Natural colours, full size. Can collect from Khaplu or pay for cargo to Lahore.', 'Before winter', 4, now() - interval '50 hours');
insert into public.shop_reviews (id, shop_id, author, from_place, rating, text, item, reply, posted_at) values
  ('r-101', 'shop-1', 'Nadia Karim', 'Jutial, Gilgit', 5, 'Walnuts came in a clean jute bag, thin shell and fresh. Delivery to Gilgit took two days. Will order again before winter.', 'walnut-akhrot-hunza', 'Shukriya Nadia! New crop apricots arrive next week.', now() - interval '72 hours'),
  ('r-102', 'shop-1', 'Asif Ali', 'Skardu City, Skardu', 5, 'Ordered three gift boxes for Eid. Nicely packed and everything was the same quality as the photo.', 'dry-fruit-gift-box-1kg-mix', null, now() - interval '216 hours'),
  ('r-103', 'shop-1', 'Farhan Baig', 'Karimabad, Hunza', 4, 'Good almonds, a few broken ones in the bag. Price is fair for Kaghzi.', 'almond-kaghzi-skardu', null, now() - interval '384 hours'),
  ('r-104', 'shop-1', 'Sana Hussain', 'Danyore, Gilgit', 5, 'Very honest shop. They told me which apricots were this year''s crop and which were last year''s.', null, null, now() - interval '648 hours'),
  ('r-201', 'shop-2', 'Imtiaz Hotel & Café', 'Skardu City, Skardu', 5, 'We buy apricots by the maund for the café. Consistent quality every time and they deliver on time.', 'dried-apricots-wholesale-maund-shigar', null, now() - interval '120 hours'),
  ('r-202', 'shop-2', 'Rukhsana Bibi', 'Shigar', 5, 'Real Shigar apricots, no sulphur smell. My children love them.', 'organic-dry-apricot-premium-shigar', null, now() - interval '288 hours'),
  ('r-203', 'shop-2', 'Kamran Shah', 'Rawalpindi', 4, 'Cargo took five days to Pindi, but the walnuts were excellent.', null, null, now() - interval '504 hours'),
  ('r-301', 'shop-3', 'Zulfiqar Ali', 'Khaplu, Ghanche', 5, 'Bought a Prado. Their mechanic showed me the inspection sheet and the papers were clean. Smooth deal.', 'toyota-prado-2021-skardu', null, now() - interval '192 hours'),
  ('r-302', 'shop-3', 'Hassan Raza', 'Skardu City, Skardu', 4, 'Good showroom, prices are a little high but the cars are in good condition.', null, null, now() - interval '456 hours'),
  ('r-303', 'shop-3', 'Mehdi Abbas', 'Shigar', 5, 'They let me take the jeep to Shigar for a test drive. Honest people.', 'suzuki-jeep-4x4-potohar-skardu', null, now() - interval '792 hours'),
  ('r-401', 'shop-4', 'Ali Madad', 'Aliabad, Hunza', 5, 'iPhone 13 came to Hunza the next day. Battery health same as written. PTA approved, checked it myself.', 'iphone-13-128gb-pta-gilgit', null, now() - interval '48 hours'),
  ('r-402', 'shop-4', 'Saima Noor', 'Jutial, Gilgit', 4, 'Screen replaced in one hour. A bit crowded in the evening, go in the morning.', null, null, now() - interval '168 hours'),
  ('r-403', 'shop-4', 'Waqar Ahmed', 'Chilas, Diamer', 5, 'Sealed box, original. Cash on delivery worked fine to Chilas.', 'airpods-pro-2nd-gen-gilgit', 'Thank you Waqar bhai, enjoy the AirPods.', now() - interval '336 hours'),
  ('r-404', 'shop-4', 'Iqbal Hussain', 'Konodas, Gilgit', 3, 'Charger was good but delivery was one day late.', null, null, now() - interval '720 hours'),
  ('r-501', 'shop-5', 'Tahira Batool', 'Gilgit', 5, 'Pure honey, it crystallises in the cold like real honey should. They sent a sample first.', 'wild-mountain-honey-nagar', null, now() - interval '96 hours'),
  ('r-502', 'shop-5', 'Shafqat Ali', 'Islamabad', 5, 'Honeycomb arrived well packed all the way to Islamabad.', 'raw-honeycomb-chhatta-nagar', null, now() - interval '432 hours'),
  ('r-601', 'shop-6', 'Maria Khan', 'Lahore', 5, 'Beautiful pattu shawl, warm and soft. You can tell it is handmade.', 'pattu-woollen-shawl-ghizer', null, now() - interval '144 hours'),
  ('r-602', 'shop-6', 'Zainab Ali', 'Skardu City, Skardu', 5, 'Ordered a custom rug in our colours. Took three weeks and was worth the wait.', 'hand-woven-balti-rug-4x6-khaplu', null, now() - interval '480 hours'),
  ('r-603', 'shop-6', 'Ahmed Raza', 'Gilgit', 4, 'Nice caps and socks. Would like more sizes.', null, null, now() - interval '840 hours'),
  ('r-701', 'shop-7', 'Usman Tariq', 'Karachi', 5, 'Rented a tent and sleeping bags for Deosai. Clean, warm and the owner explained the route.', '4-person-camping-tent-set-skardu', null, now() - interval '240 hours'),
  ('r-702', 'shop-7', 'Bilal Hussain', 'Skardu City, Skardu', 4, 'Good gear, rental rates are fair. Book early in July.', null, null, now() - interval '576 hours'),
  ('r-801', 'shop-8', 'Gul Muhammad', 'Gorikot, Astore', 5, 'Healthy sheep, vaccination card was given. Fair price for Eid.', 'astore-sheep-pair', null, now() - interval '264 hours'),
  ('r-802', 'shop-8', 'Sher Khan', 'Chilas, Diamer', 4, 'They helped arrange a pickup to Chilas. Animals arrived fine.', null, null, now() - interval '960 hours');
